function tandaPriceCard(rows, remaining) {
  const H4 = HALLOWEEN;
  const hasStrike = rows.some((r) => r.originalPrice && r.originalPrice > r.price);
  const bubble = remaining != null ? `
    <div style="text-align:center;margin:0 0 20px;">
      <span style="display:inline-block;background:#ffffff;color:${H4.violet};font-size:11px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;padding:4px 14px;border-radius:999px;margin-bottom:-12px;position:relative;">Quedan</span>
      <div style="width:116px;height:116px;margin:0 auto;border-radius:58px;background-color:${H4.lime};background-image:linear-gradient(135deg,${H4.lime},${H4.violet});text-align:center;">
        <p style="margin:0;padding-top:30px;color:${H4.bg};font-size:38px;font-weight:800;line-height:38px;">${remaining}</p>
        <p style="margin:2px 0 0;color:${H4.bg};font-size:11px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;">cupos</p>
      </div>
    </div>` : "";
  return `
    <div style="background:${H4.card};border:1px solid ${H4.border};border-radius:24px;padding:28px 22px;margin-bottom:20px;">
      ${bubble}
      <h3 style="color:${H4.lime};font-size:22px;font-weight:800;margin:0 0 6px;text-align:center;">Cupos limitados a este precio</h3>
      ${hasStrike ? `<p style="color:${H4.muted};font-size:12px;margin:0 0 16px;text-align:center;">El tachado es el precio general -- el otro es lo que pagas en esta tanda.</p>` : '<div style="height:10px;"></div>'}
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">
        ${rows.map((r) => `
        <tr>
          <td style="padding:9px 0;border-top:1px solid ${H4.border};color:${H4.ink};font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.3px;">${r.label}</td>
          <td align="right" style="padding:9px 0 9px 10px;border-top:1px solid ${H4.border};white-space:nowrap;">
            ${r.originalPrice && r.originalPrice > r.price ? `<span style="color:${H4.muted};font-size:13px;text-decoration:line-through;margin-right:8px;">${clp4(r.originalPrice)}</span>` : ""}
            <span style="color:${H4.lime};font-size:20px;font-weight:800;">${clp4(r.price)}</span>
          </td>
        </tr>`).join("")}
      </table>
    </div>`;
}
function oracleCard() {
  const H4 = HALLOWEEN;
  const url = `${BRAND.web}/disfraces?utm_source=email&utm_medium=mailing&utm_campaign=oraculo`;
  const rows = ORACLE_TEASER_CARDS.map((c) => `
    <tr>
      <td width="44" valign="middle" style="padding:10px 0 10px 12px;font-size:28px;line-height:28px;">${c.emoji}</td>
      <td valign="middle" style="padding:10px 8px;text-align:left;">
        <p style="color:${H4.violet};font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;margin:0 0 2px;">${c.tierEmoji} ${c.tierLabel}</p>
        <p style="color:${H4.ink};font-size:14px;font-weight:800;margin:0;">${c.name}</p>
      </td>
      <td valign="middle" align="right" style="padding:10px 12px 10px 0;color:${H4.lime};font-size:12px;font-weight:700;white-space:nowrap;">${c.costRange.replace(" (arriendo)", "")}</td>
    </tr>`).join("");
  const examples = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:separate;border-spacing:0 8px;margin:0 0 10px;">${rows.replace(/<tr>/g, `<tr style="background:${H4.bg};">`)}</table>`;
  return `
    <div style="background:${H4.card};border:1px solid ${H4.violet};border-radius:24px;padding:28px 20px;margin:28px 0 8px;text-align:center;box-shadow:0 0 40px rgba(186,140,255,0.18);">
      <p style="font-size:44px;margin:0 0 6px;">\u{1F52E}</p>
      <p style="color:${H4.violet};font-size:11px;font-weight:800;letter-spacing:2.5px;text-transform:uppercase;margin:0 0 8px;">Disfraz obligatorio \xB7 ${EVENT_BRAND.fechaTexto}</p>
      <h3 style="color:${H4.lime};font-size:22px;font-weight:800;margin:0 0 10px;">\xBFNo sabes de qu\xE9 disfrazarte?</h3>
      <p style="color:${H4.muted};font-size:14px;line-height:1.6;margin:0 0 18px;">Cont\xE9stale 5 preguntas al <strong style="color:${H4.ink};">Or\xE1culo de Disfraces</strong> y te revela 3 ideas hechas a tu medida: una con lo que ya tienes, una con accesorios y una full producci\xF3n.</p>
      ${examples}
      <a href="${url}" style="display:inline-block;background:${H4.violet};color:${H4.bg};text-decoration:none;padding:14px 30px;border-radius:999px;font-weight:800;font-size:14px;box-shadow:0 8px 20px rgba(186,140,255,0.3);margin-top:6px;">\u{1F52E} Consultar al Or\xE1culo</a>
      <p style="color:${H4.muted};font-size:11px;margin:12px 0 0;">Gratis, sin registro y en menos de un minuto.</p>
    </div>`;
}
function buildMailingBlastEmail(data) {
  if (data.theme) {
    return buildAnniversaryBlastEmail({
      theme: data.theme,
      buyerName: data.buyerName,
      preheader: data.preheader,
      headline: data.headline,
      paragraphs: data.paragraphs,
      ctaText: data.ctaText,
      ctaUrl: data.ctaUrl,
      secondaryCtaText: data.secondaryCtaText,
      secondaryCtaUrl: data.secondaryCtaUrl,
      highlightLabel: data.highlightLabel,
      highlightValue: data.highlightValue,
      priceList: data.priceList,
      remaining: data.remaining,
      eventInfo: data.eventInfo,
      eventSections: data.eventSections,
      tandaLabel: data.tandaLabel
    });
  }
  const H4 = HALLOWEEN;
  const greeting = data.buyerName ? `\xA1Hola, ${data.buyerName}!` : "\xA1Hola!";
  const eventInfo = data.eventInfo;
  const showBanner = data.eventSections?.banner ?? true;
  const showDetails = data.eventSections?.details ?? true;
  const showMission300 = data.eventSections?.mission300 ?? true;
  const showVenueGrid = data.eventSections?.venueGrid ?? true;
  const title = (emoji, text6) => `<h3 style="color:${H4.ink};font-size:19px;font-weight:800;margin:0 0 14px;">${emoji} ${text6}</h3>`;
  const hCard = (inner, bg = H4.card) => card(inner, { bg, borderColor: H4.border });
  const hasHighlight = !!(data.highlightLabel && data.highlightValue);
  return emailShell({
    preheader: data.preheader,
    pageBg: H4.bg,
    beforeContainer: eventInfo?.imageUrl && showBanner ? `<img src="${eventInfo.imageUrl}" alt="${eventInfo.title}" style="display:block;width:100%;height:auto;" />` : void 0,
    // Hero a medida (saludo chico arriba del titular, sin subtítulo ni CTA
    // en el encabezado -- el CTA de la campaña va más abajo, después de los
    // párrafos) -- no usa `emailHero`, que asume ese otro orden.
    hero: `
      ${eventBrandActive() ? `<div style="background-color:${H4.violet};padding:11px 20px;text-align:center;">
        <p style="color:${H4.bg};font-size:11px;font-weight:800;letter-spacing:3px;margin:0;">${EVENT_BRAND.kicker}</p>
      </div>` : ""}
      <div style="background-color:${H4.card};padding:40px 24px;text-align:center;border-radius:0 0 32px 32px;border-bottom:1px solid ${H4.border};">
        <img src="${LOGO_URL}" alt="${BRAND.nombre}" style="height:64px;width:auto;margin-bottom:24px;" />
        ${eventBrandActive() ? '<p style="font-size:52px;margin:0 0 12px;">\u{1F383}</p>' : ""}
        <p style="color:${H4.muted};font-size:14px;margin:0 0 4px;">${greeting}</p>
        <h1 style="color:${H4.lime};font-size:26px;font-weight:800;margin:0 0 16px;">${data.headline}</h1>
        ${eventBrandActive() ? `<span style="display:inline-block;background:${H4.violet};color:${H4.bg};font-size:12px;font-weight:800;letter-spacing:0.6px;padding:7px 16px;border-radius:999px;">${EVENT_BRAND.costumeBadge}</span>` : ""}
      </div>
    `,
    body: `
      ${data.paragraphs.map((p) => `
        <p style="color:${H4.muted};font-size:15px;line-height:1.6;margin:0 0 20px;">${p}</p>
      `).join("")}

      ${data.priceList && data.priceList.length > 0 ? tandaPriceCard(data.priceList, data.remaining) : ""}

      ${eventInfo && showDetails ? `
      ${title("\u{1F4C5}", eventInfo.title)}
      ${hCard(`
        <p style="color:${H4.ink};font-size:15px;margin:6px 0;">\u{1F4C5} ${eventInfo.dateText}</p>
        <p style="color:${H4.ink};font-size:15px;margin:6px 0;">\u{1F4CD} ${eventInfo.venue}${eventInfo.address ? ` \u2014 ${eventInfo.address}` : ""}</p>
        ${eventInfo.mapsUrl ? `<a href="${eventInfo.mapsUrl}" style="display:inline-block;color:${H4.violet};font-size:13px;font-weight:700;text-decoration:none;margin:4px 0 0;">\u{1F4CD} Ver en Google Maps \u2192</a>` : ""}
      `)}
      ` : ""}

      ${eventInfo?.mission300 && showMission300 ? hCard(`
        <div style="text-align:center;">
          <p style="color:${H4.muted};font-size:11px;text-transform:uppercase;letter-spacing:0.5px;margin:0 0 6px;">Misi\xF3n 300</p>
          <p style="color:${H4.lime};font-size:28px;font-weight:800;margin:0 0 10px;">${eventInfo.mission300.confirmed}/${eventInfo.mission300.goal} ya confirmados</p>
          <p style="color:${H4.ink};font-size:15px;font-weight:700;margin:0;">\u{1F383} Tu entrada sigue a $${eventInfo.mission300.depositPrice.toLocaleString("es-CL")} por persona mientras dure la Misi\xF3n 300</p>
        </div>
      `) : ""}

      ${eventInfo && showVenueGrid ? `
      ${title("\u{1F6DD}", "\xBFQu\xE9 encontrar\xE1s?")}
      ${grid(CONTENT.encontraras.map((x) => `
        <div style="background:${H4.card};border:1px solid ${H4.border};border-radius:16px;padding:14px;">
          <p style="font-size:22px;margin:0 0 4px;">${x.emoji}</p>
          <p style="color:${H4.ink};font-size:12px;font-weight:700;margin:0;">${x.label}</p>
        </div>
      `), 2)}
      ` : ""}

      ${hasHighlight ? hCard(`
        <div style="text-align:center;">
          <p style="color:${H4.muted};font-size:11px;text-transform:uppercase;letter-spacing:0.5px;margin:0 0 6px;">${data.highlightLabel}</p>
          <p style="color:${H4.lime};font-size:32px;font-weight:800;margin:0;">${data.highlightValue}</p>
        </div>
      `) : ""}

      <div style="text-align:center;padding:${hasHighlight ? "24px" : "8px"} 0 8px;">
        <a href="${data.ctaUrl}" style="display:inline-block;background:${H4.lime};color:${H4.bg};text-decoration:none;padding:14px 32px;border-radius:999px;font-weight:800;font-size:14px;box-shadow:0 8px 20px rgba(196,255,77,0.25);">${data.ctaText || "Ver m\xE1s"}</a>
      </div>

      ${data.showOracle ?? eventBrandActive() ? oracleCard() : ""}
    `
  });
}
