async function memberStats() {
  const db = await getDb();
  if (!db) return { members: 0, withPush: 0, granted: 0, used: 0, byKind: {}, recent: [] };
  const [memberRows, coupons] = await Promise.all([
    db.select({ n: sql19`count(*)` }).from(customers).where(isNotNull5(customers.memberSince)),
    db.select({
      id: memberCoupons.id,
      email: memberCoupons.email,
      kind: memberCoupons.kind,
      title: memberCoupons.title,
      createdAt: memberCoupons.createdAt,
      code: discountCodes.code,
      discountCodeId: discountCodes.id,
      usedCount: discountCodes.usedCount,
      maxUses: discountCodes.maxUses,
      validUntil: discountCodes.validUntil,
      isActive: discountCodes.isActive
    }).from(memberCoupons).innerJoin(discountCodes, eq28(memberCoupons.discountCodeId, discountCodes.id)).orderBy(desc13(memberCoupons.createdAt))
  ]);
  const byKind = {};
  let used = 0;
  for (const c of coupons) {
    const k = byKind[c.kind] ??= { granted: 0, used: 0 };
    k.granted++;
    if (c.maxUses && c.usedCount >= c.maxUses) {
      k.used++;
      used++;
    }
  }
  return {
    members: Number(memberRows[0]?.n ?? 0),
    granted: coupons.length,
    used,
    byKind,
    recent: coupons.slice(0, 100).map((c) => ({ id: c.id, discountCodeId: c.discountCodeId, email: c.email, kind: c.kind, title: c.title, code: c.code, createdAt: c.createdAt, status: couponStatus({ usedCount: c.usedCount, maxUses: c.maxUses, validUntil: c.validUntil, isActive: c.isActive }) }))
  };
}
