    aforo: `${r.attendance.toLocaleString("es-CL")} personas`,
    ingreso: clp6(r.grossIncome),
    utilidad: clp6(r.pnl.netProfit),
    margen: pct(r.pnl.marginPercent),
    meta: `${i.marginTarget}%`,
    techo: clp6(r.maxDirectExpenses),
    gastos: clp6(r.pnl.directExpensesTotal),
    equilibrio: r.breakevenTickets != null ? `${r.breakevenTickets.toLocaleString("es-CL")} entradas` : "sin equilibrio posible",
    mejora: top ? clp6(top.profitGain) : clp6(0),
