var pageCount = 0;
function newPage(doc, theme) {
  doc.addPage({ size: [W, H], margin: 0 });
  doc.page.margins.bottom = -5e3;
  doc.rect(0, 0, W, H).fill(C.bgLight);
  pageCount++;
  void theme;
}
var HEADER_BLOCKS = [
  { a: [W - 300, 0, 300, 112, C.bgDark], b: [W - 200, 38, 120, 84, C.bgDark2] },
  { a: [W - 300, 0, 300, 112, C.bgDark2], b: [W - 200, 38, 120, 84, C.bgDark] },
  { a: [W - 340, 0, 340, 100, C.bgDark], b: [W - 150, 30, 90, 90, C.bgDark2] }
];
function header(doc, kicker, title, subtitle) {
  const v = HEADER_BLOCKS[pageCount % HEADER_BLOCKS.length];
  block(doc, ...v.a, 0.85);
  block(doc, ...v.b, 0.7);
  text5(doc, String(pageCount).padStart(2, "0"), W - MX - 110, 30, { font: "display", size: 56, color: C.ink, width: 110, align: "right", height: 64 });
  rule2(doc, MX, 24, 590, 24);
  cross(doc, MX + 4, 14, 8, C.pink);
  text5(doc, kicker.toUpperCase(), MX + 16, 10, { size: 8.5, bold: true, color: C.ink, spacing: 2, width: 420, height: 12 });
  fitText(doc, title.toUpperCase(), MX, 40, { width: CONTENT_W - 200, height: 40, maxSize: 34, minSize: 18, font: "display", color: C.ink, spacing: 0.3 });
  if (subtitle) text5(doc, subtitle, MX, 88, { size: 11.5, color: C.muted, width: CONTENT_W - 200, height: 16 });
}
function footers(doc, label, o = {}) {
  const range = doc.bufferedPageRange();
  for (let i = 0; i < range.count; i++) {
    if ((o.skipFirst ?? true) && i === 0) continue;
    if (o.skipLast && i === range.count - 1) continue;
    doc.switchToPage(range.start + i);
    doc.page.margins.bottom = -5e3;
    rule2(doc, MX, 506, W - MX, 506, { width: 0.5 });
    text5(doc, `MANSION PLAYROOM  \xB7  ${label}`.toUpperCase(), MX, 512, { size: 7.5, color: C.muted, width: 640, height: 12, spacing: 1 });
    text5(doc, `${i + 1} / ${range.count}`, W - MX - 120, 512, { size: 8, color: C.muted, width: 120, align: "right" });
  }
}
var emittedText = (d) => new Intl.DateTimeFormat("es-CL", { timeZone: "America/Santiago", dateStyle: "long", timeStyle: "short" }).format(d);
function kpi(doc, x, y, w2, h, label, value, caption, color = C.ink) {
  card2(doc, x, y, w2, h);
  text5(doc, label.toUpperCase(), x + 16, y + 14, { size: 8, bold: true, color: C.muted, spacing: 1.2, width: w2 - 32, height: 12 });
  fitText(doc, value, x + 16, y + 28, { width: w2 - 32, height: 36, maxSize: 30, minSize: 18, font: "display", color, spacing: 0.4 });
  if (caption) text5(doc, caption, x + 16, y + h - 27, { size: 9.5, color: C.muted, width: w2 - 32, height: 24 });
}
var QUALITY_LABEL = { ninguno: "Sin riesgo para la calidad", bajo: "Riesgo bajo para la calidad", medio: "Con cuidado: negociar, no recortar" };
var AREA_COLOR = { ingresos: C.pink, barra: C.violet, costos: C.sky, impuestos: C.green };
function cover(doc, o) {
  newPage(doc, "dark");
  block(doc, 500, 0, 460, 346, C.bgDark, 0.9);
  block(doc, 650, 120, 310, 250, C.bgDark2, 0.78);
  doc.rect(MX - 26, 150, 10, 128).fill(C.ink);
  doc.image(logoBuffer, MX, 28, { height: 50 });
  text5(doc, "MANSION PLAYROOM", MX + 44, 46, { size: 10, bold: true, color: C.ink, spacing: 3 });
  rule2(doc, MX, 100, 470, 100);
  cross(doc, MX + 4, 116, 9, C.pink);
  text5(doc, o.kicker.toUpperCase(), MX + 18, 111, { size: 9.5, bold: true, color: C.ink, spacing: 2.5, width: 420, height: 14 });
  fitText(doc, o.title.toUpperCase(), MX, 144, { width: 540, height: 150, maxSize: 84, minSize: 28, font: "display", color: C.ink, lineGap: 0 });
  text5(doc, o.subtitle, MX, 302, { size: 12.5, color: C.ink, width: 520, height: 18 });
  if (o.verdict) pill(doc, o.verdict.label, MX, 326, { bg: VERDICT_COLOR[o.verdict.key], color: o.verdict.key === "warning" ? C.ink : C.white, size: 10.5, padX: 12, h: 22 });
  if (o.chips?.length) {
    let cx = MX;
    for (const chip of o.chips.slice(0, 4)) cx += pill(doc, chip, cx, 326, { bg: C.skySoft, color: C.ink, size: 10.5, padX: 12, h: 22 }) + 8;
  }
  const n4 = o.kpis.length;
  const colW = CONTENT_W / n4;
  rule2(doc, MX, 386, W - MX, 386, { width: 1.2 });
  o.kpis.forEach((k, i) => {
    const x = MX + i * colW;
    if (i > 0) rule2(doc, x - 10, 398, x - 10, 470, { width: 0.6 });
    text5(doc, k.label.toUpperCase(), x, 398, { size: 8.5, bold: true, color: C.muted, spacing: 1.4, width: colW - 24, height: 12 });
    fitText(doc, k.value, x, 414, { width: colW - 24, height: 50, maxSize: 50, minSize: 22, font: "display", color: k.color ?? C.ink, spacing: 0.5 });
    if (k.caption) text5(doc, k.caption, x, 470, { size: 10, color: C.muted, width: colW - 24, height: 14 });
  });
  text5(doc, `Informe generado el ${emittedText(o.emittedAt)} (hora de Chile). ${o.real ? "Cifras reales: ventas y gastos registrados hasta este momento." : "Cifras proyectadas: no incluyen ventas reales."}`, MX, 508, { size: 8, color: C.muted, width: CONTENT_W, height: 12 });
}
