  card2(doc, MX, 118, 570, 224);
  fitText(doc, d.narrative.summary, MX + 24, 138, { width: 522, height: 184, maxSize: 15.5, minSize: 11, color: C.ink, lineGap: 5 });
  const target = d.input.marginTargetPercent;
