  card2(doc, 634, 118, 278, 224);
  text5(doc, "MARGEN DE GANANCIA", 634 + 20, 134, { size: 8.5, bold: true, color: C.muted, spacing: 1, width: 238 });
  const gaugeMax = Math.max(60, Math.ceil(Math.max(margin, target) * 1.25 / 10) * 10);
  gauge(doc, 773, 270, 100, 20, Math.max(0, margin), gaugeMax, VERDICT_COLOR[d.verdict.key], target);
  text5(doc, pctText(r.pnl.marginPercent), 773 - 80, 238, { size: 30, bold: true, color: C.ink, width: 160, align: "center" });
  text5(doc, `Tu meta es ${target}%`, 773 - 80, 278, { size: 10.5, color: C.muted, width: 160, align: "center" });
  pill(doc, d.verdict.short, 773 - 58, 300, { bg: VERDICT_COLOR[d.verdict.key], color: d.verdict.key === "warning" ? C.ink : C.white, size: 10.5, padX: 12, h: 24 });
