  if (d.input.revenueTiers.length > rows.length) drawRow([`+ ${d.input.revenueTiers.length - rows.length} m\xE1s`, "", "", "", ""], false, C.muted);
  if (r.otherRevenue > 0) drawRow(["Venta de barra", `${clp7(d.input.otherRevenuePerPerson)}/pers.`, "", String(r.attendance), clp7(r.otherRevenue)], false, C.ink, "#f7f1fa");
  (d.input.extraIncomes ?? []).slice(0, 3).forEach((l) => drawRow([l.label || "Otros ingresos", clp7(l.unitPrice), String(l.quantity), "-", clp7(l.unitPrice * l.quantity)]));
  doc.save();
  doc.moveTo(tx + 20, cy).lineTo(tx + tw3 - 20, cy).lineWidth(1).stroke(C.faint);
  doc.restore();
