  text5(doc, (careful ? "CON CUIDADO  \xB7  " : "") + AREA_LABEL[rec.area].toUpperCase(), x + 26, y + 12, { size: 8, bold: true, color: accent === C.amber ? "#b7791f" : accent, spacing: 1, width: w2 - 160, height: 11 });
  fitText(doc, rec.title, x + 26, y + 26, { width: w2 - 172, height: 34, maxSize: 12.5, minSize: 9.5, bold: true, color: C.ink });
  text5(doc, `+${compact(rec.gainClp)}`, x + w2 - 126, y + 9, { font: "display", size: 20, color: "#13795B", width: 110, align: "right" });
  text5(doc, `${rec.marginPtsGain > 0 ? "+" : ""}${rec.marginPtsGain.toLocaleString("es-CL")} pts de margen`, x + w2 - 136, y + 38, { size: 8.5, color: C.muted, width: 120, align: "right" });
  fitText(doc, note, x + 26, y + 62, { width: w2 - 46, height: h - 92, maxSize: 9.5, minSize: 8, color: C.muted, lineGap: 2 });
  let px = x + 26;
