  const ticketRevenue = p.tiers.reduce((s, t4) => s + t4.price * t4.qty, 0);
  const extraTotal = p.extraIncomes.reduce((s, e) => s + e.unitPrice * e.quantity, 0);
  const otherRevenue = Math.max(0, pnl.grossIncome - ticketRevenue - extraTotal);
