function summary(doc, d) {
  let y = lightPage(doc, "Resumen para la barra", d.eventTitle);
  t(doc, "Resumen rapido", M, y, { size: 26, display: true });
  y += 38;
  const cols = [{ k: "Trago", w: 150 }, { k: "Vaso", w: 72 }, { k: "Ingredientes", w: 200 }, { k: "Opciones / extras", w: CW - 150 - 72 - 200 }];
  const head = () => {
    rr(doc, M, y, CW, 22, 6, C2.night);
    let x = M + 8;
    for (const c of cols) {
      t(doc, c.k.toUpperCase(), x, y + 7, { size: 7.5, bold: true, color: "#FFFFFF", spacing: 1 });
      x += c.w;
    }
    y += 26;
  };
  head();
  d.tragos.forEach((tr, i) => {
    const ing = tr.lineas.map((l) => `${l.name} ${l.texto}`).join(" \xB7 ");
    const op = [...tr.opciones.map((o) => `${o.label}: ${o.choices.join("/")}`), ...tr.extras].join(" \xB7 ");
    const rh = Math.max(th(doc, tr.name, cols[0].w - 10, { size: 9.5, bold: true }), th(doc, ing, cols[2].w - 10, { size: 8.5 }), th(doc, op, cols[3].w - 10, { size: 8 })) + 10;
    if (y + rh > H2 - 40) {
      y = lightPage(doc, "Resumen para la barra", d.eventTitle);
      head();
    }
    if (i % 2) rr(doc, M, y - 3, CW, rh, 4, C2.faint, { opacity: 0.45 });
    let x = M + 8;
    t(doc, tr.name, x, y + 2, { size: 9.5, bold: true, width: cols[0].w - 10 });
    x += cols[0].w;
    t(doc, `${tr.glassLabel}${tr.glassMl ? ` ${tr.glassMl}` : ""}`, x, y + 2, { size: 8.5, color: C2.pink, bold: true, width: cols[1].w - 6 });
    x += cols[1].w;
    t(doc, ing, x, y + 2, { size: 8.5, width: cols[2].w - 10 });
    x += cols[2].w;
    t(doc, op || "-", x, y + 2, { size: 8, color: C2.muted, width: cols[3].w - 10 });
    y += rh;
  });
  if (d.talCual.length) {
    y += 16;
    if (y > H2 - 120) y = lightPage(doc, "Resumen para la barra", d.eventTitle);
    t(doc, "Se sirven tal cual (botella o lata)", M, y, { size: 16, display: true });
    y += 26;
    t(doc, d.talCual.map((x) => x.name).join("  \xB7  "), M, y, { size: 10, width: CW, color: C2.ink, lineGap: 4 });
  }
}
async function buildDosierPdf(d) {
  const doc = new PDFDocument5({ size: "A4", margin: 0, autoFirstPage: false, bufferPages: true, info: { Title: safe3(`Dosier de barra - ${d.eventTitle}`), Author: "Mansion Playroom", Creator: "Mansion Playroom" } });
  doc.registerFont("Anton", Buffer.from(ANTON_TTF_BASE64, "base64"));
  const chunks = [];
  doc.on("data", (c) => chunks.push(c));
  const done = new Promise((resolve, reject) => {
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
  });
  cover2(doc, d);
  guide(doc, d);
  let y = H2;
  let section = "";
  for (const tr of d.tragos) {
    const need7 = fichaLayout(doc, tr).h + (tr.section !== section ? 40 : 0);
    if (y + need7 > H2 - 40) {
      y = lightPage(doc, "Fichas de preparacion", d.eventTitle);
      section = "";
    }
    if (tr.section !== section) {
      y = sectionHeader(doc, tr.section, y);
      section = tr.section;
    }
    y = ficha(doc, tr, y) + 14;
  }
  summary(doc, d);
  const range = doc.bufferedPageRange();
  for (let i = 1; i < range.count; i++) {
    doc.switchToPage(range.start + i);
    footer(doc, i + 1, range.count);
  }
  doc.end();
  return done;
}

