function registerSiteManifestRoute(app2) {
  app2.get("/api/site-manifest", (req, res) => {
    const t4 = typeof req.query.t === "string" && /^[A-Za-z0-9_-]{4,64}$/.test(req.query.t) ? req.query.t : null;
    const manifest = { ...MANIFEST, start_url: t4 ? `/?source=app&t=${t4}` : "/?source=app" };
    res.setHeader("Content-Type", "application/manifest+json");
    res.setHeader("Cache-Control", "private, no-store");
    res.send(JSON.stringify(manifest));
  });
  app2.get("/api/app-qr.png", async (req, res) => {
    const src = typeof req.query.src === "string" && /^[a-z0-9_-]{1,20}$/i.test(req.query.src) ? req.query.src : "qr";
    const base2 = process.env.APP_URL || "https://mansionplayroom.cl";
    const buf = await QRCode3.toBuffer(`${base2}/app?src=${src}`, { type: "png", width: 900, margin: 2, errorCorrectionLevel: "H", color: { dark: "#0b0612", light: "#ffffff" } });
    res.setHeader("Content-Type", "image/png");
    res.setHeader("Cache-Control", "public, max-age=86400");
    if (req.query.download === "1") res.setHeader("Content-Disposition", 'attachment; filename="qr-instalar-app-playroom.png"');
    res.send(buf);
  });
}

