// server/calendar.ts
init_db();
function toIcsDate(date2) {
  return date2.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
}
function icsEscape(text6) {
  return text6.replace(/\\/g, "\\\\").replace(/,/g, "\\,").replace(/;/g, "\\;").replace(/\n/g, "\\n");
}
function registerTicketAssetRoutes(app2) {
  app2.get("/api/qr/:ticketCode.png", async (req, res) => {
    const { ticketCode } = req.params;
    const ticket = await getTicketByCode(ticketCode);
    if (!ticket?.qrImageUrl?.startsWith("data:image/png;base64,")) {
      res.status(404).send("QR not found");
      return;
    }
    const base64 = ticket.qrImageUrl.slice("data:image/png;base64,".length);
    const buffer = Buffer.from(base64, "base64");
    res.setHeader("Content-Type", "image/png");
    res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
    res.send(buffer);
  });
  app2.get("/api/calendar/:ticketCode.ics", async (req, res) => {
    const { ticketCode } = req.params;
    const ticket = await getTicketByCode(ticketCode);
    if (!ticket || !ticket.eventDate) {
      res.status(404).send("Ticket not found");
      return;
    }
    const start = ticket.doorsOpen ? new Date(ticket.doorsOpen) : new Date(ticket.eventDate);
    const end = ticket.eventEnd ? new Date(ticket.eventEnd) : new Date(start.getTime() + 7 * 60 * 60 * 1e3);
    const location = [ticket.venue, ticket.address].filter(Boolean).join(", ");
    const ics = [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "PRODID:-//Mansion Playroom//Candyland//ES",
      "CALSCALE:GREGORIAN",
      "BEGIN:VEVENT",
      `UID:${ticket.ticketCode}@mansionplayroom.cl`,
      `DTSTAMP:${toIcsDate(/* @__PURE__ */ new Date())}`,
      `DTSTART:${toIcsDate(start)}`,
      `DTEND:${toIcsDate(end)}`,
      `SUMMARY:${icsEscape(ticket.eventTitle)}`,
      `LOCATION:${icsEscape(location)}`,
      `DESCRIPTION:${icsEscape(`Tu acceso: ${ticket.ticketTypeName}. C\xF3digo: ${ticket.ticketCode}`)}`,
      "END:VEVENT",
      "END:VCALENDAR"
    ].join("\r\n");
    res.setHeader("Content-Type", "text/calendar; charset=utf-8");
    res.setHeader("Content-Disposition", `attachment; filename="${ticket.eventTitle.replace(/[^a-z0-9]/gi, "-")}.ics"`);
    res.send(ics);
  });
}

// server/blobUpload.ts
import { handleUpload } from "@vercel/blob/client";
var ALLOWED_CONTENT_TYPES = [
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/gif",
  // Fondos de escena en los videos del Estudio (y el video del Hero).
  "video/mp4",
  "video/webm",
  // Videos del iPhone (.mov) para el contenido de los embajadores.
  "video/quicktime",
  // Música de los videos del Estudio.
  "audio/mpeg",
  "audio/mp4",
  "audio/x-m4a",
  "audio/aac",
  "audio/wav",
  "audio/x-wav"
];
var MAX_UPLOAD_BYTES = 50 * 1024 * 1024;
var blobToken2 = () => process.env.BLOB_READ_WRITE_TOKEN || process.env.NEW_BLOB_READ_WRITE_TOKEN;
function registerBlobUploadRoutes(app2) {
  app2.post("/api/admin/blob/upload", async (req, res) => {
    if (!await requireAdmin(req, res)) return;
    try {
      const jsonResponse = await handleUpload({
        body: req.body,
        request: req,
        token: blobToken2(),
        onBeforeGenerateToken: async () => {
          return {
            allowedContentTypes: ALLOWED_CONTENT_TYPES,
            maximumSizeInBytes: MAX_UPLOAD_BYTES,
            addRandomSuffix: true
          };
        },
        onUploadCompleted: async () => {
        }
      });
      res.json(jsonResponse);
    } catch (err) {
      res.status(400).json({ error: err instanceof Error ? err.message : "No se pudo autorizar la subida." });
    }
  });
  app2.post("/api/partner/blob/upload", async (req, res) => {
    let role = null;
    try {
      role = (await sdk.authenticateRequest(req)).role;
    } catch {
    }
    if (role !== "admin" && role !== "partner") {
      res.status(403).json({ error: "Acceso no permitido" });
      return;
    }
    try {
      const jsonResponse = await handleUpload({
        body: req.body,
        request: req,
        token: blobToken2(),
        onBeforeGenerateToken: async (pathname) => {
          if (!pathname.startsWith("coproduction/")) throw new Error("Ruta de subida no permitida.");
          return {
            allowedContentTypes: ALLOWED_CONTENT_TYPES.filter((t4) => t4.startsWith("image/")),
            maximumSizeInBytes: MAX_UPLOAD_BYTES,
            addRandomSuffix: true
          };
        },
        onUploadCompleted: async () => {
        }
      });
      res.json(jsonResponse);
    } catch (err) {
      res.status(400).json({ error: err instanceof Error ? err.message : "No se pudo autorizar la subida." });
    }
  });
}

