var DOOR_ALERT_REASONS = [
  { key: "pago", label: "Problema de pago", emoji: "\u{1F4B3}" },
  { key: "conflictivo", label: "Cliente conflictivo", emoji: "\u26A0\uFE0F" },
  { key: "entrada", label: "Entrada dudosa", emoji: "\u{1F39F}\uFE0F" },
  { key: "emergencia", label: "Emergencia", emoji: "\u{1F6A8}" },
  { key: "otro", label: "Otro", emoji: "\u{1F4AC}" }
];
var DOOR_ALERT_KEYS = DOOR_ALERT_REASONS.map((r) => r.key);
var DOOR_ALERT_NOTE_MAX = 140;
var DOOR_ALERT_COOLDOWN_MS = 2e4;
function doorAlertReason(key) {
  return DOOR_ALERT_REASONS.find((r) => r.key === key) ?? DOOR_ALERT_REASONS[DOOR_ALERT_REASONS.length - 1];
}
function cleanAlertNote(note) {
  return (typeof note === "string" ? note : "").replace(/\s+/g, " ").trim().slice(0, DOOR_ALERT_NOTE_MAX);
}
function buildDoorAlertPush(p) {
  const r = doorAlertReason(p.reason);
  const note = cleanAlertNote(p.note);
  const who3 = p.buyerName?.trim() ? ` \xB7 Cliente: ${p.buyerName.trim()}` : p.ticketCode ? ` \xB7 C\xF3digo: ${p.ticketCode}` : "";
  return {
    title: `${r.emoji} Puerta: ${r.label}`,
    body: `${p.operatorName} avisa desde la puerta${who3}${note ? ` \u2014 ${note}` : ""}`,
    url: "/admin"
  };
}

// server/caja/doorAlert.ts
async function recordDoorAlert(db, params) {
  const note = cleanAlertNote(params.note);
  const code = params.ticketCode?.trim().toUpperCase() || null;
  await applyOp(
    db,
    {
      id: params.opId,
      type: "note",
      eventId: params.eventId,
      operatorId: params.operatorId,
      targetType: "ticket",
      targetId: code ?? "puerta",
      payload: { kind: "door_alert", reason: params.reason, note: note || null, ticketCode: code, buyerName: params.buyerName ?? null },
      clientAt: params.clientAt
    },
    async () => ({ result: "applied" })
  );
  return buildDoorAlertPush({ reason: params.reason, note, operatorName: params.operatorName, ticketCode: code, buyerName: params.buyerName });
}

