// shared/voiceNote.ts
var VOICE_NOTE_RATE = 16e3;
var VOICE_NOTE_MAX_SECS = 55;
var VOICE_NOTE_MAX_BASE64 = 3e6;
function isVoiceNoteWav(bytes) {
  if (bytes.length < 44) return false;
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const ascii = (offset, n4) => String.fromCharCode.apply(null, Array.from(bytes.subarray(offset, offset + n4)));
  return ascii(0, 4) === "RIFF" && ascii(8, 4) === "WAVE" && view.getUint16(20, true) === 1 && view.getUint16(22, true) === 1 && view.getUint32(24, true) === VOICE_NOTE_RATE && view.getUint16(34, true) === 16;
}
function voiceNoteSeconds(bytes) {
  return Math.max(0, bytes.length - 44) / (VOICE_NOTE_RATE * 2);
}

// server/voiceNote.ts
async function transcribeVoiceNote(base64) {
  if (!ENV.azureSpeechKey || !ENV.azureSpeechRegion) throw new Error("Falta configurar el reconocimiento de voz (AZURE_SPEECH_KEY y AZURE_SPEECH_REGION).");
  if (base64.length > VOICE_NOTE_MAX_BASE64) throw new Error(`La nota es muy larga: m\xE1ximo ${VOICE_NOTE_MAX_SECS} segundos.`);
  const wav = new Uint8Array(Buffer.from(base64, "base64"));
  if (!isVoiceNoteWav(wav)) throw new Error("El audio no lleg\xF3 en el formato esperado. Vuelve a grabar.");
  if (voiceNoteSeconds(wav) > VOICE_NOTE_MAX_SECS + 2) throw new Error(`La nota es muy larga: m\xE1ximo ${VOICE_NOTE_MAX_SECS} segundos.`);
  const url = `https://${ENV.azureSpeechRegion}.stt.speech.microsoft.com/speech/recognition/conversation/cognitiveservices/v1?language=es-CL&format=simple&profanity=raw`;
  let res;
  try {
    res = await fetch(url, {
      method: "POST",
      headers: {
        "Ocp-Apim-Subscription-Key": ENV.azureSpeechKey,
        "Content-Type": `audio/wav; codecs=audio/pcm; samplerate=${VOICE_NOTE_RATE}`,
        Accept: "application/json",
        "User-Agent": "mansion-playroom-assistant"
      },
      body: wav,
      signal: AbortSignal.timeout(2e4)
    });
  } catch (err) {
    console.error("[VoiceNote] No se pudo hablar con Azure:", err);
    throw new Error("Azure no contest\xF3 a tiempo. Vuelve a intentarlo en un momento.");
  }
  if (!res.ok) {
    const detail = (await res.text().catch(() => "")).slice(0, 160);
    console.error("[VoiceNote] Azure respondi\xF3", res.status, detail);
    throw new Error(res.status === 401 || res.status === 403 ? "Azure rechaz\xF3 la clave de voz (AZURE_SPEECH_KEY o AZURE_SPEECH_REGION incorrectos)." : res.status === 429 ? "Azure dice que se pas\xF3 de la cuota de voz. Prueba de nuevo en un minuto." : `Azure no pudo transcribir la nota (${res.status}).`);
  }
  const data = await res.json();
  const text6 = (data.DisplayText ?? "").trim();
  if (data.RecognitionStatus !== "Success" || !text6) {
    throw new Error(data.RecognitionStatus === "InitialSilenceTimeout" || data.RecognitionStatus === "NoMatch" ? "No se escuch\xF3 nada. Acerca el tel\xE9fono y vuelve a intentarlo." : "No se entendi\xF3 la nota. Vuelve a intentarlo.");
  }
  return { text: text6 };
}

