function normalize2(raw) {
  if (!raw || !Array.isArray(raw.cards)) return null;
  const cards = [];
  for (const tier of TIERS) {
    const c = raw.cards.find((x) => x?.tier === tier);
    if (!c || typeof c.name !== "string" || !c.name.trim()) return null;
    cards.push({
      tier,
      name: String(c.name).slice(0, 80),
      emoji: String(c.emoji || "\u{1F3AD}").slice(0, 8),
      pitch: String(c.pitch || "").slice(0, 300),
      pieces: (Array.isArray(c.pieces) ? c.pieces : []).map((p) => String(p).slice(0, 100)).slice(0, 6),
      costRange: String(c.costRange || "").slice(0, 60),
      difficulty: Math.min(3, Math.max(1, Math.round(Number(c.difficulty) || 1))),
      beautyTip: String(c.beautyTip || "").slice(0, 200),
      groupTip: String(c.groupTip || "").slice(0, 200)
    });
  }
  return { intro: String(raw.intro || "").slice(0, 200), cards, fallback: false };
}
async function generateCostumeIdeas(answers) {
  try {
    const result = await invokeLLM({
      feature: "costumeOracle",
      messages: [
        { role: "system", content: buildSystemPrompt2() },
        { role: "user", content: buildUserPrompt(answers) }
      ],
      responseFormat: { type: "json_schema", json_schema: COSTUME_ORACLE_SCHEMA },
      maxTokens: 1500
    });
    const text6 = extractContent(result.choices[0]?.message ?? { content: "" });
    return normalize2(JSON.parse(text6)) ?? fallbackResult(answers.vibe);
  } catch (err) {
    console.warn("[costumeOracle] IA no disponible, se usa el cat\xE1logo est\xE1tico:", err instanceof Error ? err.message : err);
    return fallbackResult(answers.vibe);
  }
}

