async function setDemoPhase(phase) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");
  const [ev] = await db.select().from(events).where(eq78(events.slug, DEMO_EVENT_SLUG)).limit(1);
  if (!ev) throw new Error("Primero crea la cuenta de prueba");
  const w2 = demoEventWindow(phase);
  await db.update(events).set({ eventDate: w2.eventDate, doorsOpen: w2.doorsOpen, eventEnd: w2.eventEnd }).where(eq78(events.id, ev.id));
  const email = await demoEmail(db);
  const [mainOrder] = email ? await db.select().from(orders).where(and64(eq78(orders.eventId, ev.id), sql43`LOWER(${orders.buyerEmail}) = ${email}`)).limit(1) : [];
  const accessTypes = await db.select({ id: ticketTypes.id }).from(ticketTypes).where(and64(eq78(ticketTypes.eventId, ev.id), eq78(ticketTypes.name, DEMO_TICKET_TYPES[0].name)));
  if (mainOrder && accessTypes[0]) {
    await db.update(tickets).set(phase === "durante" ? { status: "used", usedAt: /* @__PURE__ */ new Date() } : { status: "valid", usedAt: null }).where(and64(eq78(tickets.orderId, mainOrder.id), eq78(tickets.ticketTypeId, accessTypes[0].id)));
  }
  const guestOrder = await db.select({ id: orders.id }).from(orders).where(and64(eq78(orders.eventId, ev.id), eq78(orders.buyerEmail, DEMO_GUESTS_EMAIL)));
  const guestTickets = guestOrder[0] ? await db.select({ id: tickets.id }).from(tickets).where(eq78(tickets.orderId, guestOrder[0].id)) : [];
  const guests = guestTickets.length > 0 ? await db.select().from(partyProfiles).where(inArray40(partyProfiles.ticketId, guestTickets.map((t4) => t4.id))) : [];
  if (guests.length > 0) await db.update(partyProfiles).set({ lastSeenAt: w2.eventEnd }).where(inArray40(partyProfiles.id, guests.map((g) => g.id)));
  const mine = mainOrder ? await db.select({ id: tickets.id }).from(tickets).where(eq78(tickets.orderId, mainOrder.id)) : [];
  const [me] = mine.length > 0 ? await db.select().from(partyProfiles).where(inArray40(partyProfiles.ticketId, mine.map((t4) => t4.id))).limit(1) : [];
  let interactions = false;
  if (me) {
    const guestIds = guests.map((g) => g.id);
    if (guestIds.length > 0) {
      const conns = await db.select().from(partyConnections).where(and64(eq78(partyConnections.eventId, ev.id), or10(inArray40(partyConnections.profileLowId, guestIds), inArray40(partyConnections.profileHighId, guestIds))));
      if (conns.length > 0) {
        await db.delete(partyMessages).where(inArray40(partyMessages.connectionId, conns.map((c) => c.id)));
        await db.delete(partyConnections).where(inArray40(partyConnections.id, conns.map((c) => c.id)));
      }
      await db.delete(partySwipes).where(and64(eq78(partySwipes.eventId, ev.id), or10(inArray40(partySwipes.fromProfileId, guestIds), eq78(partySwipes.fromProfileId, me.id))));
    }
    await db.update(partyProfiles).set({ active: phase === "durante" ? 1 : 0, rewindsUsed: 0 }).where(eq78(partyProfiles.id, me.id));
    if (phase === "durante") {
      for (const g of guests) {
        const role = DEMO_GUESTS.find((d) => d.alias === g.alias)?.role ?? "nada";
        if (role === "nada") continue;
        if (role === "like") {
          await db.insert(partySwipes).values({ eventId: ev.id, fromProfileId: g.id, toProfileId: me.id, liked: 1 });
          continue;
        }
        const { low, high } = orderedPair(g.id, me.id);
        if (role === "caramelo") {
          await db.insert(partyConnections).values({ eventId: ev.id, profileLowId: low, profileHighId: high, initiatedById: g.id, status: "pending" });
        } else {
          const connectionId = insertId2(await db.insert(partyConnections).values({ eventId: ev.id, profileLowId: low, profileHighId: high, initiatedById: g.id, status: "accepted", respondedAt: /* @__PURE__ */ new Date(), viaSwipe: 1 }));
          for (const body of DEMO_MATCH_MESSAGES) await db.insert(partyMessages).values({ connectionId, fromProfileId: g.id, body });
        }
      }
      interactions = true;
    }
  }
  return { phase, interactions };
}
async function getDemoStatus() {
  const db = await getDb();
  if (!db) return { exists: false };
  const [ev] = await db.select().from(events).where(eq78(events.slug, DEMO_EVENT_SLUG)).limit(1);
  if (!ev) return { exists: false };
  const email = await demoEmail(db);
  const phase = new Date(ev.doorsOpen ?? ev.eventDate).getTime() <= Date.now() ? "durante" : "antes";
  let enrolled = false;
  if (email) {
    const [mainOrder] = await db.select({ id: orders.id }).from(orders).where(and64(eq78(orders.eventId, ev.id), sql43`LOWER(${orders.buyerEmail}) = ${email}`)).limit(1);
    const mine = mainOrder ? await db.select({ id: tickets.id }).from(tickets).where(eq78(tickets.orderId, mainOrder.id)) : [];
    if (mine.length > 0) enrolled = (await db.select({ id: partyProfiles.id }).from(partyProfiles).where(inArray40(partyProfiles.ticketId, mine.map((t4) => t4.id))).limit(1)).length > 0;
  }
  const [amb] = email ? await db.select({ code: exclusiveAmbassadors.code }).from(exclusiveAmbassadors).where(eq78(exclusiveAmbassadors.eventId, ev.id)).limit(1) : [];
  return { exists: true, email, phase, eventDate: ev.eventDate, playmatchEnrolled: enrolled, ambassadorCode: amb?.code ?? null };
}

