async function reconcileSaldoSale(orderId, reasonNote) {
  const fail = (message) => ({ orderId, ok: false, charged: 0, shortfall: 0, balanceAfter: null, message });
  const db = await getDb();
  if (!db) return fail("Base de datos no disponible");
  const [o] = await db.select().from(orders).where(eq80(orders.id, orderId)).limit(1);
  if (!o) return fail("La venta no existe");
  if (o.channel !== "caja" || o.paymentStatus !== "approved") return fail("Solo se concilian ventas de caja aprobadas");
  if (o.paymentMethod === "saldo") return fail("Esta venta ya figura pagada con saldo");
  const saleOpId = saleOpIdOf(o.paymentId);
  if (!saleOpId) return fail("La venta no tiene identificador de caja");
  const email = o.buyerEmail.trim().toLowerCase();
  if (email === CAJA_PLACEHOLDER_EMAIL) return fail("La venta no est\xE1 asociada a ning\xFAn cliente");
  const [c] = await db.select().from(customers).where(eq80(customers.email, email)).limit(1);
  if (!c) return fail("No se encontr\xF3 la tarjeta del cliente");
  const [dup] = await db.select().from(prepaidLedger).where(and66(eq80(prepaidLedger.customerId, c.id), eq80(prepaidLedger.opId, saleOpId), eq80(prepaidLedger.reason, "spend_caja"))).limit(1);
  if (dup) return fail("Esta venta ya tiene su descuento de saldo");
  const total = Number(o.total);
  if (!(total > 0)) return fail("La venta no tiene monto");
  const charge2 = Math.min(total, Math.max(0, c.prepaidBalance));
  if (charge2 <= 0) return { orderId, ok: false, charged: 0, shortfall: total, balanceAfter: c.prepaidBalance, message: "El cliente ya no tiene saldo para descontar" };
  const [upd] = await db.update(customers).set({ prepaidBalance: sql45`prepaidBalance - ${charge2}` }).where(and66(eq80(customers.id, c.id), sql45`prepaidBalance >= ${charge2}`));
  if (Number(upd.affectedRows ?? 0) === 0) return fail("El saldo cambi\xF3 mientras se aplicaba: reintenta");
  const [after] = await db.select({ balance: customers.prepaidBalance }).from(customers).where(eq80(customers.id, c.id)).limit(1);
  const shortfall = total - charge2;
  const note = `${reasonNote} \xB7 venta ${o.orderNumber} ($${total})${shortfall > 0 ? ` \xB7 el saldo solo alcanz\xF3 para $${charge2}, faltaron $${shortfall}` : ""}`.slice(0, 500);
  try {
    await db.insert(prepaidLedger).values({ customerId: c.id, delta: -charge2, reason: "spend_caja", opId: saleOpId, balanceAfter: after.balance, note });
  } catch (err) {
    await db.update(customers).set({ prepaidBalance: sql45`prepaidBalance + ${charge2}` }).where(eq80(customers.id, c.id));
    return fail("Esta venta ya tiene su descuento de saldo");
  }
  await db.update(orders).set({ paymentMethod: "saldo" }).where(eq80(orders.id, o.id));
  return { orderId, ok: true, charged: charge2, shortfall, balanceAfter: after.balance, message: shortfall > 0 ? `Descontado $${charge2} (faltaron $${shortfall})` : `Descontado $${charge2}` };
}

