    messages: [
      // Las reglas fijas van en caché: un plan nuevo paga solo los datos del evento.
      { role: "system", content: SYSTEM_PROMPT8, cache: true },
      { role: "user", content: userContent }
    ],
    responseFormat: { type: "json_schema", json_schema: PLAN_SCHEMA },
    maxTokens: 12e3,
