async function quickJson(opts) {
  const message = await getAnthropicClient().messages.create({
    model: opts.model,
    max_tokens: opts.maxTokens,
    system: [
      { type: "text", text: opts.system, cache_control: { type: "ephemeral" } },
      ...opts.facts ? [{ type: "text", text: opts.facts }] : []
    ],
    messages: [{ role: "user", content: opts.content }],
    output_config: { ...opts.effort ? { effort: opts.effort } : {}, format: { type: "json_schema", schema: opts.schema } }
  });
  const msg = message;
  if (msg.stop_reason === "refusal") throw new Error(opts.refusal);
  if (msg.stop_reason === "max_tokens") throw new Error(opts.tooLong);
  const usage = addUsage(EMPTY_USAGE, {
    inputTokens: msg.usage.input_tokens ?? 0,
    outputTokens: msg.usage.output_tokens ?? 0,
    cacheReadTokens: msg.usage.cache_read_input_tokens ?? 0,
    cacheWriteTokens: msg.usage.cache_creation_input_tokens ?? 0
  });
  let data;
  try {
    data = JSON.parse(msg.content.map((b) => b.text ?? "").join(""));
  } catch {
    throw new Error("La IA devolvi\xF3 una respuesta rota. Intenta de nuevo.");
  }
  return { data, usage, costUsd: usageCostUsd(msg.model, usage), model: msg.model };
}

