function paymentRows(r) {
  const rows = [
    { label: "Efectivo", counted: r.countedCash, expected: r.expectedCash + r.openingCash, diff: r.cashDiff },
    { label: "D\xE9bito", counted: r.countedDebit, expected: r.expectedDebit, diff: r.debitDiff },
    { label: "Cr\xE9dito", counted: r.countedCredit, expected: r.expectedCredit, diff: r.creditDiff }
  ];
  if (r.countedQr || r.expectedQr) {
    rows.push({ label: "QR / Transferencia", counted: r.countedQr, expected: r.expectedQr, diff: r.qrDiff });
  }
  if (r.countedDebit || r.countedCredit || r.expectedDebit || r.expectedCredit) {
    const card3 = cardTotals(r);
    rows.push({ label: "Tarjetas (total)", counted: card3.counted, expected: card3.expected, diff: card3.diff });
  }
  return rows;
}
function buildShiftClosePdf(report) {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument7({ size: "A4", margin: 40 });
    const chunks = [];
    doc.on("data", (chunk) => chunks.push(chunk));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
    doc.fontSize(18).fillColor(INK2).text(`Cierre de turno \u2014 ${report.eventTitle}`);
    doc.fontSize(11).fillColor(MUTED2).text(
      `${report.registerName} \xB7 ${report.operatorName} \xB7 ${formatChileDateTime(report.closedAt)}`
    );
    doc.moveDown(0.3);
    doc.fontSize(10).fillColor(MUTED2).text(
      `Turno abierto ${formatChileDateTime(report.openedAt)} \xB7 ${report.salesCount} ventas \xB7 ${report.redeemsCount} canjes`
    );
    doc.moveDown(1.2);
    const rows = paymentRows(report);
    doc.fontSize(13).fillColor(INK2).text("Cuadre de caja");
    doc.moveDown(0.5);
    const chartBottom = drawBarChart(
      doc,
      [{ name: "Contado", color: INK2 }, { name: "Esperado", color: "#dddddd" }],
      rows.map((r) => ({ label: r.label, values: [r.counted, r.expected] })),
      doc.x,
      doc.y + 14,
      doc.page.width - doc.page.margins.left - doc.page.margins.right,
      100
    );
    doc.y = chartBottom + 16;
    const paymentTableRows = rows.map((row) => {
      const cuadra = Math.abs(row.diff) < 1;
      const diffText = cuadra ? "\u2713 Cuadra" : row.diff > 0 ? `\u25B2 Sobran ${money2(row.diff)}` : `\u25BC Faltan ${money2(Math.abs(row.diff))}`;
      return [row.label, money2(row.counted), money2(row.expected), { text: diffText, color: cuadra ? GREEN : RED }];
    });
    const afterPaymentTableY = drawTable(
      doc,
      [{ label: "Medio de pago", width: 160 }, { label: "Contado", width: 110 }, { label: "Esperado", width: 110 }, { label: "Diferencia", width: 110 }],
      paymentTableRows,
      doc.y
    );
    doc.y = afterPaymentTableY + 8;
    if (cardSplitLooksUnreliable(report)) {
      doc.fontSize(9).fillColor(RED).text(
        'Ojo: el sistema no registr\xF3 ninguna venta de un tipo de tarjeta que s\xED aparece en el voucher. El selector de la tablet qued\xF3 fijo, as\xED que las l\xEDneas de d\xE9bito y cr\xE9dito por separado no sirven para cuadrar: mira la l\xEDnea "Tarjetas (total)".'
      );
      doc.moveDown(0.3);
    }
    const paidOut = report.cashPaidOut ?? 0;
    doc.fontSize(9).fillColor(MUTED2).text(
      `Esperado en efectivo = ${money2(report.openingCash)} de fondo inicial + ${money2(report.expectedCash + paidOut)} de ventas en efectivo` + (paidOut > 0 ? ` \u2212 ${money2(paidOut)} de gastos pagados del caj\xF3n` : "") + ` = ${money2(report.expectedCash + report.openingCash)}`
    );
    doc.y = doc.y + 20;
    doc.fontSize(13).fillColor(INK2).text("Ventas del turno por producto");
    doc.moveDown(0.5);
    if (report.shiftProducts.length === 0) {
      doc.fontSize(10).fillColor(MUTED2).text("Sin ventas registradas en este turno.");
    } else {
      drawTable(
        doc,
        [{ label: "Producto", width: 280 }, { label: "Unidades", width: 100 }, { label: "Ingresos", width: 110 }],
        report.shiftProducts.map((p) => [p.name, String(p.quantity), money2(p.revenue)]),
        doc.y
      );
    }
    const voids = report.voids ?? [];
    if (voids.length > 0) {
      doc.y = doc.y + 20;
      const voidedTotal = voids.reduce((sum2, v) => sum2 + v.total, 0);
      doc.fontSize(13).fillColor(RED).text(`Ventas anuladas (${voids.length} \xB7 ${money2(voidedTotal)})`);
      doc.fontSize(9).fillColor(MUTED2).text("No suman al esperado. Cada una debe tener su reversa en la m\xE1quina o la devoluci\xF3n en efectivo.");
      doc.moveDown(0.5);
      drawTable(
        doc,
        [{ label: "Orden", width: 110 }, { label: "Cliente", width: 110 }, { label: "M\xE9todo", width: 70 }, { label: "Monto", width: 80 }, { label: "Motivo", width: 145 }],
        voids.map((v) => [v.orderNumber, v.buyerName ?? "\u2014", v.paymentMethod ?? "\u2014", money2(v.total), v.reason]),
        doc.y
      );
    }
    doc.end();
  });
}

