    // extras, aunque comparta la cola con la caja.
    sync: doorProcedure.input(z10.object({
      eventId: z10.number(),
      ops: z10.array(z10.discriminatedUnion("type", [
        z10.object({ type: z10.literal("checkin"), opId: z10.string(), ticketCode: z10.string(), clientAt: z10.string(), idVerified: z10.boolean().optional() }),
        z10.object({
          type: z10.literal("parking_paid"),
          opId: z10.string(),
          ticketCode: z10.string(),
          // Qué estacionamiento se cobró (normal o VIP). Opcional: los cobros
          // anotados antes de que existiera esta elección no lo traen.
          ticketTypeId: z10.number().optional(),
          paymentMethod: z10.enum(["efectivo", "debito", "credito"]),
          clientAt: z10.string()
        })
      ])).max(50)
    })).mutation(async ({ input, ctx }) => {
      const rawDb = await getDb();
      if (!rawDb) throw new TRPCError3({ code: "INTERNAL_SERVER_ERROR", message: "Base de datos no disponible" });
      const results = {};
      for (const op of input.ops) {
        try {
          if (op.type === "checkin") {
            results[op.opId] = await checkInTicket(rawDb, {
              opId: op.opId,
              ticketCode: op.ticketCode,
              eventId: input.eventId,
              operatorId: ctx.operator.operatorId,
              clientAt: new Date(op.clientAt),
              idVerified: op.idVerified
            });
          } else {
            results[op.opId] = await sellParkingAtDoor(rawDb, {
              opId: op.opId,
              ticketCode: op.ticketCode,
              eventId: input.eventId,
              paymentMethod: op.paymentMethod,
              ticketTypeId: op.ticketTypeId,
              operatorId: ctx.operator.operatorId,
              clientAt: new Date(op.clientAt)
            });
          }
        } catch (err) {
          results[op.opId] = { result: "rejected", conflictNote: friendlySyncErrorMessage(err, op.opId) };
        }
      }
      return results;
    })
