  /* Cross check (server/crossCheck.ts): lo que las automatizaciones y el piloto quieren hacer, esperando «Reportar». */
  crossCheck: router({
    // Los borradores de correos a personas externas se dejan listos al abrir la pantalla (una sola vez cada uno).
    list: adminReadProcedure.query(async ({ ctx }) => {
      if (ctx.user?.role !== "viewer") await Promise.resolve().then(() => (init_outreach(), outreach_exports)).then((m) => m.ensureOutreachDrafts()).catch((err) => console.error("[Outreach]", err));
      const lists = await listCrossChecks();
      return ctx.user?.role === "viewer" ? { pending: lists.pending.filter((i) => i.kind !== "outreach"), recent: lists.recent.filter((i) => i.kind !== "outreach") } : lists;
    }),
    // El correo completo de un envío por aprobar, para leerlo antes de «Reportar».
    preview: adminProcedure2.input(z10.object({ id: z10.number().int().positive() })).query(async ({ input }) => previewCrossCheck(input.id)),
    config: adminReadProcedure.query(async () => getCrossCheckConfig()),
    setAuto: adminProcedure2.input(z10.object({ kind: z10.enum(CROSS_CHECK_AUTOMATIONS), auto: z10.boolean() })).mutation(async ({ input }) => {
      await setCrossCheckAuto(input.kind, input.auto);
      return { ok: true };
    }),
    report: adminProcedure2.input(z10.object({ id: z10.number().int().positive() })).mutation(async ({ input }) => reportCrossCheck(input.id)),
    discard: adminProcedure2.input(z10.object({ id: z10.number().int().positive() })).mutation(async ({ input }) => {
      await discardCrossCheck(input.id);
      return { ok: true };
    })
  }),
