      const result = await setExpenseCogsDecision(input.id, input.decision);
      await recordAdminAudit({ action: "expenses.reviewCogs", targetType: "expense", targetId: input.id, eventId: expense.eventId ?? null, payload: { decision: input.decision }, ip: clientIp(ctx) });
      return result;
